// Parallel data fetching for the dashboard's three APIs.
// Follows the existing pattern in this codebase (see app/page.tsx):
// - fetch independent endpoints concurrently with Promise.all
// - fall back to mock data on failure so the build never breaks
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 1000, visitors: 250 },
      notifications: [{ id: 1, message: 'Welcome to your dashboard' }],
      settings: { theme: 'light', notificationsEnabled: true },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

